const contextual = new Map([
  ['比', 'ひ'], ['解', 'かい'], ['角', 'かく'], ['弧', 'こ'], ['底', 'てい'],
  ['値', 'あたい'], ['和', 'わ'], ['差', 'さ'], ['積', 'せき'], ['商', 'しょう'],
  ['根', 'こん'], ['正', 'せい'], ['負', 'ふ']
]);
const readings = new Map([
  ...[...foundationEntries, ...advancedEntries].map(entry => [entry.title, entry.reading]),
  ...supplement,
  ...contextual
]);
const escapeRegExp = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const terms = [...readings.keys()].sort((a, b) => b.length - a.length || a.localeCompare(b, 'ja'));
const pattern = new RegExp(terms.map(escapeRegExp).join('|'), 'gu');
const kanji = /[\p{Script=Han}々]/u;
const particleOrEnd = /^(?:は|が|を|の|に|と|で|から|まで|なら|だけ|[\s、。,.!?！？:：;；()（）「」『』]|$)/u;
const mathLabel = /^(?:[A-Za-zΑ-Ωα-ω0-9]|エックス|ワイ|エー|ビー|シー|ディー|イー|エフ|エヌ|エム|アール|シータ|アルファ|ベータ|ガンマ|パイ|ゼロ)/u;

function localClause(text, offset) {
  const left = text.slice(Math.max(0, offset - 100), offset).split(/[。！？!?\n]/).at(-1);
  const right = text.slice(offset, offset + 100).split(/[。！？!?\n]/)[0];
  return left + right;
}

function allowContextual(word, offset, text) {
  const before = text.slice(0, offset), after = text.slice(offset + word.length);
  // Never split another kanji word: 理解, 見解, 平和, 勝負, 大根, 値段,
  // 解説, 角度, 商品, etc. Their full words can have their own safe entries.
  if (offset && kanji.test(before.at(-1))) return false;
  if (text.trim() === word) return true;
  const clause = localClause(text, offset);
  if (word === '角') {
    if (/^(?:[A-ZΑ-Ωα-ω]|エー|ビー|シー|シータ|アルファ|ベータ|ガンマ)/u.test(after)) return true;
    if (!particleOrEnd.test(after)) return false;
    return /角の(?:大きさ|和|二等分)|三角形|四角形|多角形|内角|外角|中心角|円周角|直角|鋭角|鈍角|図形|角度|頂点|[0-9一二三四五六七八九十百]+度|ラジアン/u.test(clause);
  }
  if (word === '底') {
    if (mathLabel.test(after)) return true;
    return particleOrEnd.test(after) && /対数|指数|累乗|べき乗|log|ln|exp/u.test(clause);
  }
  if (word === '根') {
    return particleOrEnd.test(after) && /方程式|多項式|数値|探索|検出|ゼロ|0|導関数|関数|実数|複素数/u.test(clause);
  }
  if (word === '正' || word === '負') {
    return /^(?:の|なら|で|か|または|[、。\s]|$)/u.test(after)
      && /数|値|係数|指数|符号|判別式|正負|実数|正か負|正または負|ゼロ|[0-9]|エー|ビー|シー|ディー|エックス|ワイ|エム|エヌ|[a-dxy]\s*(?:は|が)/u.test(clause);
  }
  if (word === '値') return particleOrEnd.test(after);
  if (word === '弧') return particleOrEnd.test(after) || /^[A-ZΑ-Ωα-ω]/u.test(after);
  // In particular, 比べる・解く・差し引く・積もり・積み上げる・商い
  // do not start with one of these particle/standalone mathematical contexts.
  return particleOrEnd.test(after);
}

/** Convert known mathematical readings without changing the visible original. */
export function applyPronunciations(text) {
  const original = String(text ?? '');
  return original.replace(pattern, (word, offset, source) => {
    if (contextual.has(word) && !allowContextual(word, offset, source)) return word;
    if ((word === '解なし' || word === '解無し') && offset && kanji.test(source[offset - 1])) return word;
    if (/^[A-Za-z]+$/.test(word)) {
      const before = source[offset - 1] || '', after = source[offset + word.length] || '';
      if (/[A-Za-z0-9_]/.test(before) || /[A-Za-z0-9_]/.test(after)) return word;
    }
    return readings.get(word);
  });
}
